def f(g):
    n=len(g); m=len(g[0]); offs={ (j-i) for i in range(n) for j in range(m) if g[i][j]!=0 }
    p=len(offs); P={}
    for i in range(n):
        for j in range(m):
            if g[i][j]!=0:
                P[(j-i)%p]=g[i][j]
    return [[P.get((j-i)%p,0) for j in range(m)] for i in range(n)]
